import java.util.HashMap;
import java.util.Map;

public class CharUtils {

    private static final Map<Character, Character> cache = new HashMap<>();

    /**
     * Converts the character to a Character.
     * For ASCII 7 bit characters, this uses a cache that will return the same Character object each time.
     *
     * @param ch the character to convert
     * @return a Character of the specified character
     */
    public static Character toCharacterObject(final char ch) {
        char lowerCaseCh = Character.toLowerCase(ch);
        if (lowerCaseCh >= 0 && lowerCaseCh <= 127) {
            synchronized (cache) {
                return cache.computeIfAbsent(ch, k -> k);
            }
        } else {
            return new Character(ch);
        }
    }

    public static void main(String[] args) {
        System.out.println(toCharacterObject(' ')); // Should return a cached Character object for ' '
        System.out.println(toCharacterObject('A')); // Should return a cached Character object for 'A'
        System.out.println(toCharacterObject('a')); // Should return a cached Character object for 'a'
        System.out.println(toCharacterObject('é')); // Should return a new Character object for 'é'
    }
}

