        if (minCapacity - bytes.length > 0) {
            int newCapacity = bytes.length * 2;
            if (newCapacity - minCapacity < 0) {
                newCapacity = minCapacity;
            }
            bytes = Arrays.copyOf(bytes, newCapacity);
        }
    }

