public class ConstantPoolReader {

    private final byte[] classFileBuffer;

    public ConstantPoolReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    /**
     * Reads a CONSTANT_Utf8 constant pool entry in the {@link #classFileBuffer}.
     * @param constantPoolEntryIndex the index of a CONSTANT_Utf8 entry in the class's constant pool table.
     * @param charBuffer the buffer to be used to read the string. This buffer must be sufficiently large. It is not automatically resized.
     * @return the String corresponding to the specified CONSTANT_Utf8 entry.
     */
    final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
        // Get the length of the UTF-8 string
        int index = constantPoolEntryIndex * 3;
        int length = (classFileBuffer[index] & 0xFF) << 8 | (classFileBuffer[index + 1] & 0xFF);

        // Adjust the index to point to the start of the UTF-8 bytes
        index += 2;

        // Copy the UTF-8 bytes into the charBuffer
        for (int i = 0; i < length; i++) {
            int b1 = classFileBuffer[index++];
            int b2 = classFileBuffer[index++];
            if ((b1 & 0x80) == 0) {
                charBuffer[i] = (char) b1;
