import java.io.File;
import java.io.IOException;

public class FileDeleter {

    /**
     * Schedules a file to be deleted when JVM exits. If file is directory delete it and all sub-directories.
     * @param file  file or directory to delete, must not be {@code null}
     * @throws NullPointerException if the file is {@code null}
     * @throws IOException in case deletion is unsuccessful
     */
    public static void forceDeleteOnExit(File file) throws IOException {
        if (file == null) {
            throw new NullPointerException("File is null");
        }

        if (file.isDirectory()) {
            for (File subFile : file.listFiles()) {
                if (subFile.isDirectory()) {
                    forceDeleteOnExit(subFile);
                } else {
                    subFile.deleteOnExit();
                }
            }
        }
        file.deleteOnExit();
    }

    public static void main(String[] args) {
        try {
            File file = new File("path/to/your/file/or/directory");
            forceDeleteOnExit(file);
            System.out.println("File or directory scheduled for deletion on JVM exit.");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

