        if (head == null) {
            return false;
        }

        if (head == node) {
            head = head.next;
            return true;
        }

        ListNodeImpl<E> current = head;
        while (current != null && current.next != null) {
            if (current.next == node) {
                current.next = node.next;
                return true;
