    if (array == null) {
        return 0;
    }
    int hash = 1;
    for (long l : array) {
        int high = (int) (l >>> 32);
        int low = (int) (l & 0xFFFFFFFFL);
        hash = 31 * hash + high;
        hash = 31 * hash + low;
    }
    return hash;
}

