    public LoggingEvent get() {
        if (size > 0) {
            LoggingEvent event = buffer[head];
            head = (head + 1) % buffer.length;
            size--;
            return event;
        }
        return null;
    }

    public boolean hasEntries() {
        return size > 0;
    }
}

