static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 100000000L;
    long month = (timeBucket / 1000000L) % 100L;
    long day = (timeBucket / 10000L) % 100L;

    if (day >= dayStep) {
        day -= dayStep - 1;
        if (day > 0) {
            // Adjust month and year if necessary
        } else {
            day = 1;
            if (month == 1) {
                month = 12;
                year--;
            } else {
                month--;
            }
        }
    }

    return year * 100000000L + month * 1000000L + day * 10000L;
}

