public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[1024]; // Initial capacity
        this.size = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteArrayValue == null) {
            Arrays.fill(data, size, size + byteLength, (byte) 0);
        } else {
            ensureCapacity(size + byteLength);
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
        }
        size += byteLength;
        return this;
    }

    private void ensureCapacity(int minCapacity) {
        if (minCapacity - data.length > 0) {
            int newCapacity = Math.max(data.length << 1, minCapacity);
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    @Override
    public String toString() {
        return Arrays.toString(data);
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byteVector.putByteArray(new byte[]{1, 2, 3}, 0, 3)
                   .putByteArray(null, 0, 5)
                   .putByteArray(new byte[]{4, 5}, 0, 2);
        System.out.println(byteVector);
    }
}

