public class StackOperations {

    private Stack<Object> outputFrameStack;

    public StackOperations() {
        this.outputFrameStack = new Stack<>();
    }

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        int count = 0;
        for (char c : descriptor.toCharArray()) {
            if (isTypeDescriptor(c)) {
                outputFrameStack.pop();
                count++;
            }
        }
    }

    private boolean isTypeDescriptor(char c) {
        switch (c) {
            case 'Z': // boolean
            case 'B': // byte
            case 'C': // char
            case 'S': // short
            case 'I': // int
            case 'F': // float
            case 'J': // long
            case 'D': // double
            case 'L': // reference
            case '[': // array
                return true;
            default:
                return false;
        }
    }

    public static void main(String[] args) {
        StackOperations stackOperations = new StackOperations();
        // Example usage
        stackOperations.outputFrameStack.push("booleanValue");
        stackOperations.outputFrameStack.push("byteValue");
        stackOperations.outputFrameStack.push("charValue");
        stackOperations.outputFrameStack.push("shortValue");
        stackOperations.outputFrameStack.push("intValue");
        stackOperations.outputFrameStack.push("floatValue");
        stackOperations.outputFrameStack.push("longValue");
        stackOperations.outputFrameStack.push("doubleValue");
        stackOperations.outputFrameStack.push("referenceValue");
        stackOperations.outputFrameStack.push("arrayValue");

        stackOperations.pop("Ljava/lang/String;[IJ[LDDB");

        System.out.println(stackOperations.outputFrameStack.size()); // Expected: 2
    }
}

